{"code": "import math
try:
    from pyproj import Transformer
    ok = True
except Exception as e:
    ok = False
    print("pyproj not available:", e)

pts_wgs = {   # (lat, lon) WGS84
    "Emirates":   (51.55500, -0.10833),
    "St Marys":   (50.90583, -1.39111),
    "Vitality":   (50.73528, -1.83833),
}

def shoelace(v):
    n=len(v); tot=0.0
    for i in range(n):
        x1,y1=v[i]; x2,y2=v[(i+1)%n]
        tot += x1*y2 - x2*y1
    return abs(tot)/2.0

if ok:
    # British National Grid (OSGB36) - the standard "UK map" projection
    t_bng = Transformer.from_crs("EPSG:4326", "EPSG:27700", always_xy=True)
    grid = {}
    for k,(la,lo) in pts_wgs.items():
        x,y = t_bng.transform(lo, la)
        grid[k]=(x/1000.0, y/1000.0)
    print("British National Grid (km):")
    for k,v in grid.items(): print("  ", k, f"{v[0]:.4f} E, {v[1]:.4f} N")
    A_bng = shoelace(list(grid.values()))
    print(f"\nArea (BNG shoelace):  {A_bng:.2f} km^2")

    # UTM zone 30N
    t_utm = Transformer.from_crs("EPSG:4326", "EPSG:32630", always_xy=True)
    utm = {k: tuple(c/1000.0 for c in t_utm.transform(lo, la)) for k,(la,lo) in pts_wgs.items()}
    print(f"Area (UTM 30N shoelace): {shoelace(list(utm.values())):.2f} km^2")

    # side lengths geodesic
    from pyproj import Geod
    g = Geod(ellps="WGS84")
    keys=list(pts_wgs)
    for i in range(3):
        for j in range(i+1,3):
            _,_,d = g.inv(pts_wgs[keys[i]][1], pts_wgs[keys[i]][0], pts_wgs[keys[j]][1], pts_wgs[keys[j]][0])
            print(f"  geodesic {keys[i]}-{keys[j]}: {d/1000:.3f} km")"}

